-- =====================================================================
-- UNTSF-COMM: fixed armaments, built into the frame (Muv-Luv wiki, Fixed Armament).
--   Adds the 'Fixed armament' mount type, nine catalogue items (Wire Cutter, Spike
--   Vane, Blade Edge Armour, Close-Range Fixed Melee Armament, Blade Motor, Large
--   Blade Motor, CIDS Mk. 1 Javelin, Retractable Dagger, Clawed Manipulator), and
--   fixed mounts with their factory fit on the frames that carry them, by model, so
--   variants added later get them too. Blade Motors are now fixed armaments, so the
--   bay-mounted Forearm Motor Blade comes out of Soviet factory fits.
--   Only adds what's missing; never changes a catalogue item or mount that exists.
--   Safe to run twice. Machines' own saved configurations are not touched.
-- =====================================================================

do $$
declare
    spec    constant jsonb := '{"slot":{"code":"fixed_armament","name":"Fixed armament"},"equipment":[{"id":"eq-fa-wire-cutter","code":"EQ-0048","name":"Wire Cutter","category":"melee_weapon","manufacturerId":null,"rating":40,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Hardened guard built into the head unit of MiG and Su frames. Shields the main optics and cuts away anything that snags them.","weapon":null,"modifiers":[{"stat":"tsf.durability","value":1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-mig21","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig23","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig25","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig27","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig29ovt","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-su27","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-su37m2","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-spike-vane","code":"EQ-0049","name":"Spike Vane","category":"melee_weapon","manufacturerId":null,"rating":48,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Super-carbon blades fixed to the shoulder blocks, a Soviet design. Short reach, used to shed Tank-class at speed.","weapon":{"damage":12,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Proximity defence: cuts Tank-class that close in during evasive manoeuvres"},"modifiers":[{"stat":"tsf.defence","value":2}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-su27","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-su37m2","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig29ovt","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-ef2000","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-blade-edge","code":"EQ-0050","name":"Blade Edge Armour","category":"melee_weapon","manufacturerId":null,"rating":50,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Sharpened, shock-hardened armour edges built into the frame itself: legs, fingertips, head crest. Defensive, not a weapon to fight with.","weapon":{"damage":10,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Proximity defence only; edges wear with use and are costly to maintain"},"modifiers":[{"stat":"tsf.defence","value":2},{"stat":"tsf.durability","value":1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-su27","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-su37m2","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-type00","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-ef2000","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-j10x","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-fixed-blades","code":"EQ-0051","name":"Close-Range Fixed Melee Armament","category":"melee_weapon","manufacturerId":null,"rating":52,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Blades mounted on the arms or feet as part of the frame, as on the Typhoon. Built for BETA, not for duelling other TSFs.","weapon":{"damage":18,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Pre-installed arm or foot blades; little effect on human-made armour"},"modifiers":[{"stat":"tsf.defence","value":1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-ef2000","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-blade-motor","code":"EQ-0052","name":"Blade Motor","category":"melee_weapon","manufacturerId":null,"rating":66,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Arm-mounted chain blades, first fitted to the Su-27SM. Cuts through almost anything; the belt of blades is replaced whole.","weapon":{"damage":30,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Usable while grappled; cuts through TSF armour"},"modifiers":[],"engine":null,"compat":[{"effect":"allow","type":"variant","targetId":"var-su27-sm","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-su37m2","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-mig29ovt","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-large-blade-motor","code":"EQ-0053","name":"Large Blade Motor","category":"melee_weapon","manufacturerId":null,"rating":68,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"The heavier leg-mounted Blade Motor of the MiG-29 line, with triangular teeth.","weapon":{"damage":34,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Leg-mounted; usable while grappled"},"modifiers":[{"stat":"tsf.mobility","value":-1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-mig29ovt","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-javelin","code":"EQ-0054","name":"CIDS Mk. 1 Javelin","category":"melee_weapon","manufacturerId":null,"rating":58,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Spiked armour plates on the A-10 that fire out on explosive pellets and reel back in, repeatedly. Bulky, but it keeps the Tank-class off.","weapon":{"damage":20,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Fires spikes into Tank-class latched onto the frame; needs explosive pellets loaded"},"modifiers":[{"stat":"tsf.durability","value":3},{"stat":"tsf.mobility","value":-1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-a10","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-retractable-dagger","code":"EQ-0055","name":"Retractable Dagger","category":"melee_weapon","manufacturerId":null,"rating":64,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Arm-mounted super-carbon dagger of the Type-00 Takemikazuchi, out and in faster than any drawn knife.","weapon":{"damage":26,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Deploys faster than a drawn close-combat knife"},"modifiers":[{"stat":"tsf.handling","value":1}],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-type00","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null},{"id":"eq-fa-clawed-manipulator","code":"EQ-0056","name":"Clawed Manipulator","category":"melee_weapon","manufacturerId":null,"rating":42,"weight":"light","availability":"standard","origin":"canon","publishStatus":"published","slots":["fixed_armament"],"description":"Hand units with super-carbon claws on the A-6 and A-12 attackers, for when the BETA are already on top of them.","weapon":{"damage":14,"accuracy":0,"range":"melee","fireRate":null,"magazine":null,"reload":null,"special":"Last-ditch; poor against anything larger than Tank-class"},"modifiers":[],"engine":null,"compat":[{"effect":"allow","type":"model","targetId":"mdl-a6","match":null,"reason":"RESTRICTED: Built into other frames."},{"effect":"allow","type":"model","targetId":"mdl-a12","match":null,"reason":"RESTRICTED: Built into other frames."}],"unlock":[],"duplicatedFrom":null}],"byModel":{"mdl-mig21":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"}],"mdl-mig23":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"}],"mdl-mig25":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"}],"mdl-mig27":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"}],"mdl-su27":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"},{"code":"FA_SHOULDERS","label":"Fixed armament · shoulders","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-spike-vane"},{"code":"FA_LEGS","label":"Fixed armament · legs","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-edge"}],"mdl-su37m2":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"},{"code":"FA_SHOULDERS","label":"Fixed armament · shoulders","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-spike-vane"},{"code":"FA_ARMS","label":"Fixed armament · arms","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-motor"},{"code":"FA_LEGS","label":"Fixed armament · legs","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-edge"}],"mdl-mig29ovt":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-wire-cutter"},{"code":"FA_SHOULDERS","label":"Fixed armament · shoulders","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-spike-vane"},{"code":"FA_ARMS","label":"Fixed armament · arms","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-motor"},{"code":"FA_LEGS","label":"Fixed armament · legs","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-large-blade-motor"}],"mdl-ef2000":[{"code":"FA_HEAD","label":"Fixed armament · head","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-edge"},{"code":"FA_SHOULDERS","label":"Fixed armament · shoulders","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-spike-vane"},{"code":"FA_ARMS","label":"Fixed armament · arms","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-fixed-blades"},{"code":"FA_LEGS","label":"Fixed armament · legs","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-fixed-blades"}],"mdl-j10x":[{"code":"FA_LEGS","label":"Fixed armament · legs","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-edge"}],"mdl-type00":[{"code":"FA_FRAME","label":"Fixed armament · frame","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-edge"},{"code":"FA_ARMS","label":"Fixed armament · arms","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-retractable-dagger"}],"mdl-a10":[{"code":"FA_FRAME","label":"Fixed armament · frame","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-javelin"}],"mdl-a6":[{"code":"FA_HANDS","label":"Fixed armament · hands","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-clawed-manipulator"}],"mdl-a12":[{"code":"FA_HANDS","label":"Fixed armament · hands","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-clawed-manipulator"}]},"byVariant":{"var-su27-sm":[{"code":"FA_ARMS","label":"Fixed armament · arms","slots":["fixed_armament"],"maxWeight":"heavy","fixed":true,"factory":"eq-fa-blade-motor"}]},"strip":{"models":["mdl-mig21","mdl-mig23","mdl-mig25","mdl-mig27","mdl-mig29ovt","mdl-su27","mdl-su37m2"],"mounts":["FOREARM_L","FOREARM_R"],"item":"eq-motorblade"}}'::jsonb;
    item    jsonb;
    m       jsonb;
    rec     record;
    hps     jsonb;
    dl      jsonb;
    wants   jsonb;
    mount   text;
    touched boolean;
    n_items integer := 0;
    n_vars  integer := 0;
begin
    update public.docs set data = jsonb_set(data, '{items}', coalesce(data->'items', '[]'::jsonb) || jsonb_build_array(spec->'slot'))
     where collection = 'vocab' and id = 'slot_types'
       and not exists (select 1 from jsonb_array_elements(coalesce(data->'items', '[]'::jsonb)) x where x->>'code' = 'fixed_armament');

    for item in select * from jsonb_array_elements(spec->'equipment') loop
        insert into public.docs (collection, id, data) values ('equipment', item->>'id', item) on conflict (collection, id) do nothing;
        if found then n_items := n_items + 1; end if;
    end loop;

    for rec in select id, data from public.docs where collection = 'variants' loop
        wants := coalesce(spec->'byModel'->(rec.data->>'modelId'), '[]'::jsonb) || coalesce(spec->'byVariant'->rec.id, '[]'::jsonb);
        hps := coalesce(rec.data->'hardpoints', '[]'::jsonb);
        dl := coalesce(rec.data->'defaultLoadout', '{}'::jsonb);
        if jsonb_typeof(dl) <> 'object' then dl := '{}'::jsonb; end if;
        touched := false;
        for m in select * from jsonb_array_elements(wants) loop
            if not exists (select 1 from jsonb_array_elements(hps) h where h->>'code' = m->>'code') then
                hps := hps || jsonb_build_array(m - 'factory'); touched := true;
            end if;
            if coalesce(dl->>(m->>'code'), '') = '' then
                dl := dl || jsonb_build_object(m->>'code', m->>'factory'); touched := true;
            end if;
        end loop;
        if (spec->'strip'->'models') ? (rec.data->>'modelId') then
            foreach mount in array array(select jsonb_array_elements_text(spec->'strip'->'mounts')) loop
                if dl->>mount = spec->'strip'->>'item' then dl := dl - mount; touched := true; end if;
            end loop;
        end if;
        if touched then
            update public.docs set data = jsonb_set(jsonb_set(data, '{hardpoints}', hps), '{defaultLoadout}', dl)
             where collection = 'variants' and id = rec.id;
            n_vars := n_vars + 1;
        end if;
    end loop;
    raise notice 'fixed armaments: % catalogue items added, % variants updated', n_items, n_vars;
end $$;
